{"file_path": "src/lru.js", "content": "/**
 * 一个固定容量的 LRU（Least Recently Used）缓存。
 *
 * 行为约定：
 * - `get(key)` 命中时返回值并把该键标记为最近使用；未命中返回 `undefined`。
 * - `put(key, value)` 写入或更新条目，更新同样会刷新为最近使用；
 *   条目数超过容量时淘汰最久未使用的条目。
 * - `size` 是只读 getter，返回当前条目数。
 *
 * 键的相等语义沿用 `Map`（SameValueZero）：对象按引用比较、`NaN` 可作为键、
 * `-0` 与 `+0` 视为同一个键。
 *
 * 注意：命中判定基于键是否存在，而不是值是否为 `undefined`。因此存入
 * `undefined` 的键仍算命中且占用容量；但调用方无法仅凭 `get` 的返回值区分
 * “命中且值为 undefined”与“未命中”。本类不提供 `has`/`peek`。
 */
export class LRUCache {
  /** @type {number} */
  #capacity;

  /**
   * 插入顺序 = 从最久未使用到最近使用。
   * @type {Map<unknown, unknown>}
   */
  #entries = new Map();

  /**
   * @param {number} capacity 容量，必须是正整数。
   * @throws {RangeError} 当容量不是正整数时抛出。
   */
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new RangeError(`capacity must be a positive integer, got ${capacity}`);
    }
    this.#capacity = capacity;
  }

  /** @returns {number} 当前条目数。 */
  get size() {
    return this.#entries.size;
  }

  /**
   * 读取条目并将其标记为最近使用。
   * @param {unknown} key
   * @returns {unknown} 命中时返回对应值，未命中返回 `undefined`。
   */
  get(key) {
    if (!this.#entries.has(key)) return undefined;
    const value = this.#entries.get(key);
    this.#entries.delete(key); // 先删再插，把键移到队尾（最近使用）
    this.#entries.set(key, value);
    return value;
  }

  /**
   * 写入或更新条目，必要时淘汰最久未使用的条目。
   * @param {unknown} key
   * @param {unknown} value
   * @returns {void}
   */
  put(key, value) {
    if (this.#entries.has(key)) {
      this.#entries.delete(key); // 更新已有键也要刷新为最近使用
    } else if (this.#entries.size >= this.#capacity) {
      this.#entries.delete(this.#entries.keys().next().value); // 队首 = 最久未使用
    }
    this.#entries.set(key, value);
  }
}

export default LRUCache;
"}

