{"content": "import test from 'node:test';
import assert from 'node:assert/strict';

import DefaultExport, { LRUCache } from '../src/lru.js';

test('导出形态：默认导出与命名导出是同一个类，可实例化', () => {
  assert.strictEqual(DefaultExport, LRUCache);
  assert.strictEqual(typeof LRUCache, 'function');
  const lru = new LRUCache(2);
  assert.ok(lru instanceof LRUCache);
  assert.strictEqual(lru.size, 0);
});

test('未命中：空缓存返回 undefined 且 size 不变', () => {
  const lru = new LRUCache(2);
  assert.strictEqual(lru.get('x'), undefined);
  assert.strictEqual(lru.size, 0);
});

test('基本读写：put 后 get 返回原值，size 增加', () => {
  const lru = new LRUCache(2);
  lru.put('a', 1);
  assert.strictEqual(lru.get('a'), 1);
  assert.strictEqual(lru.size, 1);
});

test('命中刷新顺序：get 后的键不会被优先淘汰', () => {
  const lru = new LRUCache(2);
  lru.put('a', 1);
  lru.put('b', 2);
  assert.strictEqual(lru.get('a'), 1); // a 变为最近使用
  lru.put('c', 3); // 应淘汰 b

  assert.strictEqual(lru.get('b'), undefined);
  assert.strictEqual(lru.get('a'), 1);
  assert.strictEqual(lru.get('c'), 3);
  assert.strictEqual(lru.size, 2);
});

test('更新已存在键：不增加 size，并刷新为最近使用', () => {
  const lru = new LRUCache(2);
  lru.put('a', 1);
  lru.put('b', 2);
  lru.put('a', 9); // 更新 a，a 变为最近使用
  assert.strictEqual(lru.size, 2);
  lru.put('c', 3); // 应淘汰 b

  assert.strictEqual(lru.get('b'), undefined);
  assert.strictEqual(lru.get('a'), 9);
  assert.strictEqual(lru.size, 2);
});

test('连续写入：条目数不超过容量，只保留最近写入的条目', () => {
  const lru = new LRUCache(3);
  for (let i = 0; i < 100; i += 1) {
    lru.put(i, i);
  }
  assert.strictEqual(lru.size, 3);
  assert.strictEqual(lru.get(97), 97);
  assert.strictEqual(lru.get(98), 98);
  assert.strictEqual(lru.get(99), 99);
  assert.strictEqual(lru.get(96), undefined);
});

test('容量为 1：每次写入新键都淘汰旧键', () => {
  const lru = new LRUCache(1);
  lru.put('a', 1);
  assert.strictEqual(lru.size, 1);
  lru.put('b', 2);
  assert.strictEqual(lru.size, 1);
  assert.strictEqual(lru.get('a'), undefined);
  assert.strictEqual(lru.get('b'), 2);
});

test('非法容量：非正整数全部抛 RangeError', () => {
  for (const capacity of [0, -3, 2.5, NaN, Infinity, '3', null, undefined]) {
    assert.throws(
      () => new LRUCache(capacity),
      RangeError,
      `capacity=${String(capacity)} 应抛 RangeError`,
    );
  }
});

test('size 是只读属性：读取正确，赋值抛 TypeError', () => {
  const lru = new LRUCache(2);
  assert.strictEqual(lru.size, 0);
  lru.put('a', 1);
  assert.strictEqual(lru.size, 1);
  lru.put('a', 2);
  assert.strictEqual(lru.size, 1);
  lru.put('b', 3);
  lru.put('c', 4);
  assert.strictEqual(lru.size, 2);

  assert.throws(() => {
    lru.size = 99;
  }, TypeError);
  assert.strictEqual(lru.size, 2);
});

test('值类型保真：假值与非原始值原样返回', () => {
  const lru = new LRUCache(5);
  const obj = { id: 1 };
  lru.put('null', null);
  lru.put('zero', 0);
  lru.put('false', false);
  lru.put('empty', '');
  lru.put('obj', obj);

  assert.strictEqual(lru.get('null'), null);
  assert.strictEqual(lru.get('zero'), 0);
  assert.strictEqual(lru.get('false'), false);
  assert.strictEqual(lru.get('empty'), '');
  assert.strictEqual(lru.get('obj'), obj);
});

test('未命中不影响淘汰顺序', () => {
  const lru = new LRUCache(2);
  lru.put('a', 1);
  lru.put('b', 2);
  assert.strictEqual(lru.get('z'), undefined); // 未命中不应改变顺序
  lru.put('c', 3); // 仍应淘汰 a

  assert.strictEqual(lru.get('a'), undefined);
  assert.strictEqual(lru.get('b'), 2);
  assert.strictEqual(lru.get('c'), 3);
  assert.strictEqual(lru.size, 2);
});

test('被淘汰的键不会复活，且不改变 size', () => {
  const lru = new LRUCache(1);
  lru.put('a', 1);
  lru.put('b', 2); // 淘汰 a
  assert.strictEqual(lru.get('a'), undefined);
  assert.strictEqual(lru.size, 1);
  assert.strictEqual(lru.get('b'), 2);
});

test('值为 undefined 也占用容量并参与淘汰', () => {
  const lru = new LRUCache(1);
  lru.put('u', undefined);
  assert.strictEqual(lru.size, 1);
  lru.put('v', 1); // 应淘汰 u

  assert.strictEqual(lru.size, 1);
  assert.strictEqual(lru.get('u'), undefined);
  assert.strictEqual(lru.get('v'), 1);
});
", "file_path": "test/lru.test.js"}

